def test_render_missing_column_raises_value_error():
    """Referencing a non-existent column must raise ValueError with legible message."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [1.0, 2.0]})
    spec = fr.ChartSpec(mark="point", x="totally_missing", y="y")
    with pytest.raises(ValueError):
        fr.render_svg(spec, df, viewport=(600.0, 400.0))


def test_render_invalid_viewport_raises_value_error():
    """Zero-width viewport must raise ValueError."""
    df = pl.DataFrame({"x": [1.0], "y": [1.0]})
    spec = fr.ChartSpec(mark="point", x="x", y="y")
    with pytest.raises(ValueError):
        fr.render_svg(spec, df, viewport=(0.0, 400.0))


def test_render_invalid_color_theme_raises_value_error():
    """Invalid hex color in theme must raise ValueError."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [1.0, 2.0]})
    spec = fr.ChartSpec(mark="point", x="x", y="y")
    with pytest.raises(ValueError):
        fr.render_svg(spec, df, viewport=(600.0, 400.0), theme={"mark_color": "not-a-color"})


# ---------------------------------------------------------------------------
# Spec round-trips
# ---------------------------------------------------------------------------


def test_chartspec_json_roundtrip_mark_field_preserved():
    """ChartSpec JSON round-trip must preserve mark and encoding fields."""
    spec = fr.ChartSpec(mark="point", x="xvar", y="yvar")
    json_str = spec.to_json()
    spec2 = fr.ChartSpec.from_json(json_str)
    assert spec2 == spec


def test_chartspec_json_roundtrip_color_encoding_preserved():
    """Color encoding must survive JSON serialization round-trip."""
    spec = fr.ChartSpec(mark="point", x="a", y="b", color="cat")
    spec2 = fr.ChartSpec.from_json(spec.to_json())
    assert spec2 == spec


