def test_chart_no_encoding_does_not_crash():
    """A Chart with no encoding fields must not crash (returns valid SVG or raises cleanly)."""
    df = pl.DataFrame({"x": [1.0, 2.0], "y": [1.0, 2.0]})
    spec = fr.ChartSpec(mark="point", x="x", y="y")
    # Basic render: this is mainly testing no segfault or panic
    svg = fr.render_svg(spec, df, viewport=(600.0, 400.0))
    assert "<svg " in svg


def test_pyarrow_table_boundary_renders_correctly():
    """Arrow CDI boundary test: pyarrow Table must render identically to polars DataFrame."""
    df = pl.DataFrame({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    table = pa.table({"x": [1.0, 2.0, 3.0], "y": [10.0, 20.0, 30.0]})
    spec = fr.ChartSpec(mark="point", x="x", y="y")
    svg_pl = fr.render_svg(spec, df, viewport=(600.0, 400.0))
    svg_pa = fr.render_svg(spec, table, viewport=(600.0, 400.0))
    # Both must produce the same circle count
    assert svg_pl.count("<circle") == svg_pa.count("<circle") == 3
